import { useId, type ReactNode } from 'react';
import { cx } from '@/shared/lib/classNames';
import styles from './Switch.module.scss';

export interface SwitchProps {
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
  /** Visible label, on the left; clicking it toggles the switch. */
  label: ReactNode;
  /** Help under the label (« Fait pendant la remontée »), read as the description. */
  hint?: ReactNode;
  disabled?: boolean;
  /** Id of the switch button (generated by default). */
  id?: string;
  className?: string | undefined;
}

/**
 * On / off toggle with its label (dive-form.jsx · SwitchRow): a `<button role="switch">` with
 * `aria-checked`, 44 × 26 track. The content it reveals stays with the caller.
 */
export function Switch({
  checked,
  onCheckedChange,
  label,
  hint,
  disabled = false,
  id,
  className,
}: SwitchProps) {
  const generatedId = useId();
  const switchId = id ?? `${generatedId}-switch`;
  const hintId = `${generatedId}-hint`;

  return (
    <div className={cx(styles.row, className)}>
      <div className={styles.text}>
        <label htmlFor={switchId} className={styles.label}>
          {label}
        </label>
        {hint && (
          <span id={hintId} className={styles.hint}>
            {hint}
          </span>
        )}
      </div>
      <button
        id={switchId}
        type="button"
        role="switch"
        aria-checked={checked}
        aria-describedby={hint ? hintId : undefined}
        disabled={disabled}
        className={styles.track}
        onClick={() => onCheckedChange(!checked)}
      >
        <span className={styles.thumb} aria-hidden="true" />
      </button>
    </div>
  );
}
